#[derive(Debug, Deserialize, Default)]
pub struct LogsQueryParams {
    pub start: Option<i64>,
    pub end: Option<i64>,
    pub stream: Option<bool>,
    pub download: Option<bool>,
}

async fn api_service_logs(
    State(state): State<AppState>,
    jar: CookieJar,
    headers: HeaderMap,
    AxumPath(service): AxumPath<String>,
    Query(q): Query<LogsQueryParams>,
) -> Response {
    if let Err(err_resp) = authorize_admin_read(&state, &jar, &headers).await {
        return err_resp.into_response();
    }
    if q.download == Some(true) {
        let (_, lines) = state.log_hub.query_lines(&service, None, None);
        let body = format!("{}\n", lines.join("\n"));
        return ([(header::CONTENT_TYPE, "text/plain; charset=utf-8")], body).into_response();
    }

    if q.stream == Some(true) {
        let rx = state.log_hub.subscribe();
        let svc = service.clone();
        let stream = async_stream_lines(svc, rx);
        return (
            [
                (header::CONTENT_TYPE, "text/plain; charset=utf-8"),
                (header::CACHE_CONTROL, "no-cache"),
            ],
            Body::from_stream(stream),
        )
            .into_response();
    }

    let (total, lines) = state.log_hub.query_lines(&service, q.start, q.end);
    Json(json!({
        "totalLines": total,
        "lines": lines
    }))
    .into_response()
}

fn async_stream_lines(
    service: String,
    rx: broadcast::Receiver<(String, String)>,
) -> impl futures_util::Stream<Item = std::result::Result<bytes::Bytes, std::io::Error>> {
    futures_util::stream::unfold((service, rx), |(svc, mut rx)| async move {
        loop {
            match rx.recv().await {
                Ok((msg_svc, line)) => {
                    if msg_svc == svc {
                        let out = bytes::Bytes::from(format!("{line}\n"));
                        return Some((Ok(out), (svc, rx)));
                    }
                }
                Err(broadcast::error::RecvError::Lagged(_)) => continue,
                Err(broadcast::error::RecvError::Closed) => return None,
            }
        }
    })
}

fn escape_prom_label_value(raw: &str) -> String {
    let mut out = String::with_capacity(raw.len());
    for ch in raw.chars() {
        match ch {
            '\\' => out.push_str("\\\\"),
            '"' => out.push_str("\\\""),
            '\n' => out.push_str("\\n"),
            '\r' => {}
            _ => out.push(ch),
        }
    }
    out
}

fn filter_stats_snapshot_for_allowed_cameras(val: &mut Value, allow_list: &[String]) {
    if allow_list.iter().any(|a| a == "*") {
        return;
    }
    let is_permitted = |cam: &str| {
        let base = cam.strip_suffix("_sub").unwrap_or(cam).trim();
        allow_list.iter().any(|a| a == cam || a == base)
    };
    let mut retained_cam_fps = 0.0;
    let mut retained_det_fps = 0.0;
    if let Some(cams) = val.get_mut("cameras").and_then(|v| v.as_object_mut()) {
        cams.retain(|k, _| is_permitted(k));
        for c_stat in cams.values() {
            retained_cam_fps += c_stat
                .get("camera_fps")
                .and_then(|v| v.as_f64())
                .unwrap_or(0.0);
            retained_det_fps += c_stat
                .get("detection_fps")
                .and_then(|v| v.as_f64())
                .unwrap_or(0.0);
        }
    }
    if let Some(obj) = val.as_object_mut() {
        let rounded_cam = (retained_cam_fps * 10.0).round() / 10.0;
        let rounded_det = (retained_det_fps * 10.0).round() / 10.0;
        obj.insert("camera_fps".to_string(), json!(rounded_cam));
        obj.insert("process_fps".to_string(), json!(rounded_cam));
        obj.insert("detection_fps".to_string(), json!(rounded_det));
    }
    if let Some(service_obj) = val.get_mut("service").and_then(|s| s.as_object_mut()) {
        if let Some(cam_storage) = service_obj
            .get_mut("camera_storage")
            .and_then(|v| v.as_object_mut())
        {
            cam_storage.retain(|k, _| is_permitted(k));
        }
        if let Some(heuristics) = service_obj
            .get_mut("heuristics")
            .and_then(|v| v.as_array_mut())
        {
            heuristics.retain(|h| {
                let cat = h.get("category").and_then(|v| v.as_str()).unwrap_or("");
                let target = h.get("target").and_then(|v| v.as_str()).unwrap_or("");
                if matches!(cat, "vision" | "streams" | "audio") {
                    let targets: Vec<&str> = target
                        .split(',')
                        .map(str::trim)
                        .filter(|s| !s.is_empty())
                        .collect();
                    !targets.is_empty() && targets.into_iter().all(is_permitted)
                } else {
                    true
                }
            });
        }
    }
}

async fn api_stats_history(
    State(state): State<AppState>,
    jar: CookieJar,
    headers: HeaderMap,
) -> Json<Value> {
    let allowed = caller_allowed_cameras(&state, &jar, &headers).await;
    let history = state.stats_history.read().await;
    if history.is_empty() {
        drop(history);
        let mut current = compute_stats_snapshot(&state).await;
        if let Some(ref allow_list) = allowed {
            filter_stats_snapshot_for_allowed_cameras(&mut current, allow_list);
        }
        return Json(json!([current]));
    }
    let mut items: Vec<Value> = history.iter().cloned().collect();
    if let Some(ref allow_list) = allowed {
        for item in &mut items {
            filter_stats_snapshot_for_allowed_cameras(item, allow_list);
        }
    }
    Json(Value::Array(items))
}

/// Appends `ninjanvr_detector_inference_ms` samples. Only measured latencies are exported: an
/// idle or unloaded detector has no latency, and a placeholder would make dashboards show
/// inference that never happened.
fn render_detector_inference_metrics(stats_val: &Value, out: &mut String) {
    let measured_ms = |d_stat: &Value| -> Option<f64> {
        if d_stat.get("measured").and_then(|v| v.as_bool()) == Some(false) {
            return None;
        }
        d_stat.get("inference_speed").and_then(|v| v.as_f64())
    };
    if let Some(primary) = stats_val.get("primary_detector")
        && let Some(ms) = measured_ms(primary)
    {
        out.push_str(&format!(
            "ninjanvr_detector_inference_ms{{detector=\"primary\"}} {ms:.2}\n"
        ));
    }
    if let Some(dets) = stats_val.get("detectors").and_then(|v| v.as_object()) {
        for (det_name, d_stat) in dets {
            let Some(ms) = measured_ms(d_stat) else {
                continue;
            };
            let safe_det = escape_prom_label_value(det_name);
            out.push_str(&format!(
                "ninjanvr_detector_inference_ms{{detector=\"{safe_det}\"}} {ms:.2}\n"
            ));
        }
    }
}

async fn api_prometheus_metrics(
    State(state): State<AppState>,
    jar: CookieJar,
    headers: HeaderMap,
) -> Response {
    let allowed = caller_allowed_cameras(&state, &jar, &headers).await;
    let mut stats_val = compute_stats_snapshot(&state).await;
    if let Some(ref allow_list) = allowed {
        filter_stats_snapshot_for_allowed_cameras(&mut stats_val, allow_list);
    }
    let mut out = String::with_capacity(4096);

    out.push_str("# HELP ninjanvr_camera_fps Per-camera frame rate by pipeline role.\n");
    out.push_str("# TYPE ninjanvr_camera_fps gauge\n");
    out.push_str(
        "# HELP ninjanvr_camera_online Camera stream online status (1 = online, 0 = offline).\n",
    );
    out.push_str("# TYPE ninjanvr_camera_online gauge\n");

    if let Some(cams) = stats_val.get("cameras").and_then(|v| v.as_object()) {
        for (cam, c_stat) in cams {
            let safe_cam = escape_prom_label_value(cam);
            let cam_fps = c_stat
                .get("camera_fps")
                .and_then(|v| v.as_f64())
                .unwrap_or(0.0);
            let det_fps = c_stat
                .get("detection_fps")
                .and_then(|v| v.as_f64())
                .unwrap_or(0.0);
            let proc_fps = c_stat
                .get("process_fps")
                .and_then(|v| v.as_f64())
                .unwrap_or(cam_fps);
            let online = if cam_fps > 0.0 { 1 } else { 0 };
            out.push_str(&format!(
                "ninjanvr_camera_fps{{camera=\"{safe_cam}\",role=\"camera\"}} {cam_fps:.2}\n"
            ));
            out.push_str(&format!(
                "ninjanvr_camera_fps{{camera=\"{safe_cam}\",role=\"detect\"}} {det_fps:.2}\n"
            ));
            out.push_str(&format!(
                "ninjanvr_camera_fps{{camera=\"{safe_cam}\",role=\"process\"}} {proc_fps:.2}\n"
            ));
            out.push_str(&format!(
                "ninjanvr_camera_online{{camera=\"{safe_cam}\"}} {online}\n"
            ));
        }
    }

    out.push_str(
        "# HELP ninjanvr_detector_inference_ms AI detector inference latency in milliseconds.\n",
    );
    out.push_str("# TYPE ninjanvr_detector_inference_ms gauge\n");
    render_detector_inference_metrics(&stats_val, &mut out);

    out.push_str("# HELP ninjanvr_storage_used_bytes Used bytes on storage mounts.\n");
    out.push_str("# TYPE ninjanvr_storage_used_bytes gauge\n");
    out.push_str("# HELP ninjanvr_storage_total_bytes Total bytes on storage mounts.\n");
    out.push_str("# TYPE ninjanvr_storage_total_bytes gauge\n");
    if let Some(storages) = stats_val
        .get("service")
        .and_then(|s| s.get("storage"))
        .and_then(|v| v.as_object())
    {
        for (mount_path, st) in storages {
            let raw_label = if mount_path.contains("recordings") {
                "recordings"
            } else if mount_path.contains("clips") {
                "clips"
            } else if mount_path.contains("cache") {
                "cache"
            } else if mount_path.contains("shm") {
                "shm"
            } else {
                mount_path.as_str()
            };
            let label = escape_prom_label_value(raw_label);
            let used_mb = st.get("used").and_then(|v| v.as_f64()).unwrap_or(0.0);
            let total_mb = st.get("total").and_then(|v| v.as_f64()).unwrap_or(0.0);
            let used_bytes = (used_mb * 1024.0 * 1024.0).round() as u64;
            let total_bytes = (total_mb * 1024.0 * 1024.0).round() as u64;
            out.push_str(&format!(
                "ninjanvr_storage_used_bytes{{mount=\"{label}\"}} {used_bytes}\n"
            ));
            out.push_str(&format!(
                "ninjanvr_storage_total_bytes{{mount=\"{label}\"}} {total_bytes}\n"
            ));
        }
    }

    let sys_cpu = stats_val
        .get("cpu_usages")
        .and_then(|c| c.get("ninjanvr.full_system"))
        .and_then(|f| f.get("cpu"))
        .and_then(|v| v.as_str())
        .and_then(|s| s.parse::<f64>().ok())
        .unwrap_or(0.0);
    let sys_mem_pct = stats_val
        .get("cpu_usages")
        .and_then(|c| c.get("ninjanvr.full_system"))
        .and_then(|f| f.get("mem"))
        .and_then(|v| v.as_str())
        .and_then(|s| s.parse::<f64>().ok())
        .unwrap_or(0.0);
    out.push_str("# HELP ninjanvr_cpu_usage_percent Process CPU usage percentage.\n");
    out.push_str("# TYPE ninjanvr_cpu_usage_percent gauge\n");
    out.push_str(&format!("ninjanvr_cpu_usage_percent {sys_cpu:.2}\n"));
    out.push_str("# HELP ninjanvr_memory_usage_bytes Process resident memory usage in bytes.\n");
    out.push_str("# TYPE ninjanvr_memory_usage_bytes gauge\n");
    out.push_str(&format!(
        "ninjanvr_memory_usage_bytes {}\n",
        (sys_mem_pct * 1024.0 * 1024.0).round() as u64
    ));

    out.push_str("# HELP ninjanvr_events_total Total persisted object detection events by camera and label.\n");
    out.push_str("# TYPE ninjanvr_events_total counter\n");
    if let Ok(ev_counts) = state.db.query_event_counts_by_camera_and_label() {
        for (cam, lbl, cnt) in ev_counts {
            if let Some(ref allow_list) = allowed
                && !allow_list.iter().any(|a| a == &cam || a == "*")
            {
                continue;
            }
            let safe_cam = escape_prom_label_value(&cam);
            let safe_lbl = escape_prom_label_value(&lbl);
            out.push_str(&format!(
                "ninjanvr_events_total{{camera=\"{safe_cam}\",label=\"{safe_lbl}\"}} {cnt}\n"
            ));
        }
    }

    (
        [(
            header::CONTENT_TYPE,
            "text/plain; version=0.0.4; charset=utf-8",
        )],
        out,
    )
        .into_response()
}

#[derive(Debug, Deserialize, Default)]
pub struct AiContextQueryParams {
    pub hours: Option<f64>,
    pub after: Option<f64>,
    pub before: Option<f64>,
}

async fn build_ai_context_digest(
    state: &AppState,
    hours: f64,
    after_opt: Option<f64>,
    before_opt: Option<f64>,
    allowed_cameras: Option<&[String]>,
) -> Value {
    let now = unix_now() as f64;
    let before = before_opt.filter(|v| v.is_finite()).unwrap_or(now + 5.0);
    let safe_hours = if hours.is_finite() { hours } else { 24.0 };
    let clamped_hours = safe_hours.clamp(0.1, 720.0);
    let after = after_opt
        .filter(|v| v.is_finite())
        .unwrap_or(before - clamped_hours * 3600.0);

    let cfg = state.config.read().await;
    let metrics_map = state.camera_metrics.read().await;
    let mut cameras_health = serde_json::Map::new();
    for (cam_name, cam_cfg) in &cfg.cameras {
        if let Some(allowed) = allowed_cameras
            && !allowed.iter().any(|a| a == cam_name || a == "*")
        {
            continue;
        }
        let m = metrics_map.get(cam_name);
        let rt_flags = state.comms.get_camera_flags(cam_name);
        let fps = m.map_or(
            if cam_cfg.enabled {
                cam_cfg.detect.fps as f64
            } else {
                0.0
            },
            |x| x.camera_fps,
        );
        cameras_health.insert(
            cam_name.clone(),
            json!({
                "enabled": rt_flags.enabled,
                "online": fps > 0.0 || cam_cfg.enabled,
                "fps": fps,
                "detection_fps": m.map_or(0.0, |x| x.detection_fps),
                "night_mode": m.is_some_and(|x| x.night_mode),
                "detect": rt_flags.detect,
                "record": rt_flags.record,
                "alerts": rt_flags.alerts
            }),
        );
    }

    let db_allowed: Option<&[String]> = match allowed_cameras {
        Some(list) if list.iter().any(|a| a == "*") => None,
        other => other,
    };
    let db_digest = state
        .db
        .query_ai_digest_summary(after, before, db_allowed)
        .unwrap_or_else(|_| json!({}));

    json!({
        "service": {
            "version": NINJANVR_VERSION,
            "active_profile": state.comms.get_active_profile(),
            "storage_degraded": state.storage_degraded.load(std::sync::atomic::Ordering::Relaxed)
        },
        "cameras": cameras_health,
        "digest": db_digest
    })
}

async fn api_ai_context(
    State(state): State<AppState>,
    jar: CookieJar,
    headers: HeaderMap,
    Query(q): Query<AiContextQueryParams>,
) -> Json<Value> {
    let allowed = caller_allowed_cameras(&state, &jar, &headers).await;
    let hours = q.hours.unwrap_or(24.0);
    let digest =
        build_ai_context_digest(&state, hours, q.after, q.before, allowed.as_deref()).await;
    Json(digest)
}

#[derive(Debug, Deserialize)]
pub struct McpJsonRpcRequest {
    #[serde(default)]
    pub jsonrpc: String,
    #[serde(default)]
    pub id: Value,
    pub method: String,
    #[serde(default)]
    pub params: Value,
}

async fn api_mcp_handler(
    State(state): State<AppState>,
    uri: Uri,
    jar: CookieJar,
    headers: HeaderMap,
    Json(req): Json<McpJsonRpcRequest>,
) -> Response {
    let id = req.id.clone();
    if !verify_cookie_csrf_origin(&headers, &uri) {
        return (
            StatusCode::FORBIDDEN,
            Json(json!({
                "jsonrpc": "2.0",
                "id": id,
                "error": {
                    "code": -32003,
                    "message": "Cross-origin cookie request rejected (Origin/Host mismatch)"
                }
            })),
        )
            .into_response();
    }
    let caller_role = {
        let cfg = state.config.read().await;
        let has_creds = headers.contains_key(header::AUTHORIZATION)
            || jar.get(&cfg.auth.cookie_name).is_some()
            || (cfg.auth.proxy.enabled && extract_trusted_proxy_peer_ip(&headers).is_some());
        match extract_authenticated_user_with_cfg(&state, &jar, &headers, &cfg.auth) {
            Some((_, r)) => r.to_ascii_lowercase(),
            None if cfg.auth.enabled && has_creds => "unauthorized".to_string(),
            None => "admin".to_string(),
        }
    };
    if caller_role == "unauthorized" || caller_role == "metrics" {
        let status = if caller_role == "unauthorized" {
            StatusCode::UNAUTHORIZED
        } else {
            StatusCode::FORBIDDEN
        };
        return (
            status,
            Json(json!({
                "jsonrpc": "2.0",
                "id": id,
                "error": {
                    "code": -32003,
                    "message": "Unauthorized or insufficient token scope for MCP"
                }
            })),
        )
            .into_response();
    }
    let allowed = caller_allowed_cameras(&state, &jar, &headers).await;

    match req.method.as_str() {
        "initialize" => Json(json!({
            "jsonrpc": "2.0",
            "id": id,
            "result": {
                "protocolVersion": "2024-11-05",
                "serverInfo": {
                    "name": "ninjanvr-mcp",
                    "version": NINJANVR_VERSION
                },
                "capabilities": {
                    "tools": {}
                }
            }
        }))
        .into_response(),
        "notifications/initialized" | "notifications/cancelled" => {
            StatusCode::ACCEPTED.into_response()
        }
        "ping" => Json(json!({
            "jsonrpc": "2.0",
            "id": id,
            "result": {}
        }))
        .into_response(),
        "tools/list" => Json(json!({
            "jsonrpc": "2.0",
            "id": id,
            "result": {
                "tools": [
                    {
                        "name": "get_security_digest",
                        "description": "Returns a structured summary of camera health, object/alert counts by camera/label/zone, and unreviewed alerts with deep links.",
                        "inputSchema": {
                            "type": "object",
                            "properties": {
                                "hours": { "type": "number", "default": 24 }
                            }
                        }
                    },
                    {
                        "name": "search_events",
                        "description": "Searches detected object events by camera, label, zone, or minimum confidence score.",
                        "inputSchema": {
                            "type": "object",
                            "properties": {
                                "camera": { "type": "string" },
                                "label": { "type": "string" },
                                "zone": { "type": "string" },
                                "limit": { "type": "integer", "default": 25 }
                            }
                        }
                    },
                    {
                        "name": "get_camera_status",
                        "description": "Returns live health, FPS, night IR state, and runtime flags for all permitted cameras.",
                        "inputSchema": {
                            "type": "object",
                            "properties": {}
                        }
                    },
                    {
                        "name": "set_security_profile",
                        "description": "Switches the active operational security profile (armed, home, disarmed).",
                        "inputSchema": {
                            "type": "object",
                            "properties": {
                                "profile": { "type": "string", "enum": ["armed", "home", "disarmed"] }
                            },
                            "required": ["profile"]
                        }
                    }
                ]
            }
        }))
        .into_response(),
        "tools/call" => {
            let tool_name = req
                .params
                .get("name")
                .and_then(|v| v.as_str())
                .unwrap_or("");
            let args = req
                .params
                .get("arguments")
                .cloned()
                .unwrap_or_else(|| json!({}));

            match tool_name {
                "get_security_digest" => {
                    let hours = args.get("hours").and_then(|v| v.as_f64()).unwrap_or(24.0);
                    let digest =
                        build_ai_context_digest(&state, hours, None, None, allowed.as_deref())
                            .await;
                    Json(json!({
                        "jsonrpc": "2.0",
                        "id": id,
                        "result": {
                            "content": [{ "type": "text", "text": digest.to_string() }],
                            "structuredContent": digest
                        }
                    }))
                    .into_response()
                }
                "search_events" | "query_events" => {
                    let mut parsed_cams: Vec<String> = Vec::new();
                    for key in ["camera", "cameras"] {
                        match args.get(key) {
                            Some(Value::String(s)) => {
                                for part in s.split(',') {
                                    let t = part.trim();
                                    if !t.is_empty() {
                                        parsed_cams.push(t.to_string());
                                    }
                                }
                            }
                            Some(Value::Array(arr)) => {
                                for item in arr {
                                    if let Some(s) = item.as_str() {
                                        let t = s.trim();
                                        if !t.is_empty() {
                                            parsed_cams.push(t.to_string());
                                        }
                                    }
                                }
                            }
                            _ => {}
                        }
                    }
                    let req_cams = if parsed_cams.is_empty() {
                        None
                    } else {
                        Some(parsed_cams)
                    };
                    let filter = EventFilter {
                        cameras: scope_cameras_filter(req_cams, allowed),
                        labels: args
                            .get("label")
                            .and_then(|v| v.as_str())
                            .map(str::trim)
                            .filter(|s| !s.is_empty())
                            .map(|s| vec![s.to_string()]),
                        exclude_labels: None,
                        zones: args
                            .get("zone")
                            .and_then(|v| v.as_str())
                            .map(str::trim)
                            .filter(|s| !s.is_empty())
                            .map(|s| vec![s.to_string()]),
                        sub_labels: None,
                        plate: args
                            .get("plate")
                            .and_then(|v| v.as_str())
                            .map(str::trim)
                            .filter(|s| !s.is_empty())
                            .map(str::to_string),
                        recognized_license_plates: None,
                        favorites: None,
                        min_score: args.get("min_score").and_then(|v| v.as_f64()),
                        stationary: None,
                        before: args.get("before").and_then(|v| v.as_f64()),
                        after: args.get("after").and_then(|v| v.as_f64()),
                        limit: Some(
                            args.get("limit")
                                .and_then(|v| v.as_u64())
                                .unwrap_or(25)
                                .clamp(1, 500) as usize,
                        ),
                    };
                    let db_for_mcp = state.db.clone();
                    let mut events =
                        tokio::task::spawn_blocking(move || db_for_mcp.query_events(&filter))
                            .await
                            .ok()
                            .and_then(|r| r.ok())
                            .unwrap_or_default();
                    redact_event_slice_thumbnails_if_masked(&state.config, &mut events).await;
                    let val = json!({ "events": events, "count": events.len() });
                    Json(json!({
                        "jsonrpc": "2.0",
                        "id": id,
                        "result": {
                            "content": [{ "type": "text", "text": val.to_string() }],
                            "structuredContent": val
                        }
                    }))
                    .into_response()
                }
                "get_camera_status" | "get_camera_health" => {
                    let digest =
                        build_ai_context_digest(&state, 1.0, None, None, allowed.as_deref()).await;
                    let health = json!({
                        "service": digest["service"],
                        "cameras": digest["cameras"]
                    });
                    Json(json!({
                        "jsonrpc": "2.0",
                        "id": id,
                        "result": {
                            "content": [{ "type": "text", "text": health.to_string() }],
                            "structuredContent": health
                        }
                    }))
                    .into_response()
                }
                "set_security_profile" => {
                    if !verify_cookie_csrf_origin(&headers, &uri) {
                        return (
                            StatusCode::FORBIDDEN,
                            Json(json!({
                                "jsonrpc": "2.0",
                                "id": id,
                                "error": {
                                    "code": -32003,
                                    "message": "Cross-origin cookie request rejected (Origin/Host mismatch)"
                                }
                            })),
                        )
                            .into_response();
                    }
                    let caller_role = {
                        let cfg = state.config.read().await;
                        let has_creds = headers.contains_key(header::AUTHORIZATION)
                            || jar.get(&cfg.auth.cookie_name).is_some()
                            || (cfg.auth.proxy.enabled
                                && extract_trusted_proxy_peer_ip(&headers).is_some());
                        match extract_authenticated_user_with_cfg(
                            &state,
                            &jar,
                            &headers,
                            &cfg.auth,
                        ) {
                            Some((_, r)) => r.to_ascii_lowercase(),
                            None if cfg.auth.enabled && has_creds => "unauthorized".to_string(),
                            None => "admin".to_string(),
                        }
                    };
                    if caller_role == "viewer"
                        || caller_role == "read_only"
                        || caller_role == "metrics"
                        || caller_role == "unauthorized"
                        || allowed.is_some()
                    {
                        return (
                            StatusCode::FORBIDDEN,
                            Json(json!({
                                "jsonrpc": "2.0",
                                "id": id,
                                "error": {
                                    "code": -32003,
                                    "message": "Read-only or camera-restricted role or token cannot modify security profile"
                                }
                            })),
                        )
                            .into_response();
                    }
                    let prof = args
                        .get("profile")
                        .and_then(|v| v.as_str())
                        .unwrap_or("armed");
                    let active = state.comms.set_active_profile(prof);
                    let res_val = json!({ "success": true, "active_profile": active });
                    Json(json!({
                        "jsonrpc": "2.0",
                        "id": id,
                        "result": {
                            "content": [{ "type": "text", "text": res_val.to_string() }],
                            "structuredContent": res_val
                        }
                    }))
                    .into_response()
                }
                _ => (
                    StatusCode::BAD_REQUEST,
                    Json(json!({
                        "jsonrpc": "2.0",
                        "id": id,
                        "error": {
                            "code": -32601,
                            "message": format!("Unknown MCP tool: {tool_name}")
                        }
                    })),
                )
                    .into_response(),
            }
        }
        _ => (
            StatusCode::BAD_REQUEST,
            Json(json!({
                "jsonrpc": "2.0",
                "id": id,
                "error": {
                    "code": -32601,
                    "message": format!("Method not found: {}", req.method)
                }
            })),
        )
            .into_response(),
    }
}

#[derive(Debug, Deserialize)]
pub struct DebugReprocessBody {
    pub camera: String,
    pub start_time: f64,
    pub end_time: f64,
    #[serde(default)]
    pub override_config: Option<Value>,
    #[serde(default)]
    pub min_score: Option<f64>,
    #[serde(default)]
    pub min_area: Option<f64>,
    #[serde(default)]
    pub max_area: Option<f64>,
}

async fn api_debug_reprocess(
    State(state): State<AppState>,
    uri: Uri,
    jar: CookieJar,
    headers: HeaderMap,
    Json(body): Json<DebugReprocessBody>,
) -> Response {
    if !verify_cookie_csrf_origin(&headers, &uri) {
        return (
            StatusCode::FORBIDDEN,
            Json(json!({
                "success": false,
                "message": "Cross-origin cookie request rejected (Origin/Host mismatch)"
            })),
        )
            .into_response();
    }
    if !caller_can_mutate(&state, &jar, &headers, true).await {
        return (
            StatusCode::FORBIDDEN,
            Json(json!({
                "success": false,
                "message": "Admin role required"
            })),
        )
            .into_response();
    }
    if !is_safe_go2rtc_stream_name(&body.camera) {
        return (
            StatusCode::BAD_REQUEST,
            Json(json!({ "success": false, "message": "Invalid camera identifier" })),
        )
            .into_response();
    }
    if !body.start_time.is_finite() || !body.end_time.is_finite() || body.start_time < 0.0 {
        return (
            StatusCode::BAD_REQUEST,
            Json(json!({ "success": false, "message": "Invalid start_time or end_time" })),
        )
            .into_response();
    }
    if let Some(allowed) = caller_allowed_cameras(&state, &jar, &headers).await
        && !allowed.iter().any(|a| a == &body.camera || a == "*")
    {
        return (
            StatusCode::FORBIDDEN,
            Json(json!({ "success": false, "message": "Camera is not permitted for this user" })),
        )
            .into_response();
    }
    let Ok(_reprocess_permit) = state.debug_reprocess_semaphore.try_acquire() else {
        return (
            StatusCode::TOO_MANY_REQUESTS,
            Json(json!({
                "success": false,
                "message": "A debug reprocess job is already in progress"
            })),
        )
            .into_response();
    };

    let start_ts = body.start_time;
    let end_ts = body.end_time.min(start_ts + 120.0).max(start_ts + 1.0);

    let (cam_cfg, cold_dir_opt) = {
        let cfg = state.config.read().await;
        (
            cfg.cameras.get(&body.camera).cloned().unwrap_or_default(),
            resolve_configured_cold_dir(&cfg),
        )
    };

    let (det_w, det_h, frame_bytes_len) =
        pipeline::sanitize_yuv420p_dimensions(cam_cfg.detect.width, cam_cfg.detect.height);
    let frame_area = (det_w as f64) * (det_h as f64);

    let ov = body.override_config.as_ref();
    let eff_min_score = body
        .min_score
        .or_else(|| ov.and_then(|v| v.get("min_score")).and_then(|v| v.as_f64()))
        .filter(|v| v.is_finite())
        .unwrap_or(0.50);
    let raw_min_area = body
        .min_area
        .or_else(|| ov.and_then(|v| v.get("min_area")).and_then(|v| v.as_f64()))
        .filter(|v| v.is_finite())
        .unwrap_or(0.0);
    let eff_min_area_px = if raw_min_area > 0.0 && raw_min_area <= 1.0 {
        (raw_min_area * frame_area).round() as u32
    } else {
        raw_min_area.max(0.0).round() as u32
    };
    let raw_max_area = body
        .max_area
        .or_else(|| ov.and_then(|v| v.get("max_area")).and_then(|v| v.as_f64()))
        .filter(|v| v.is_finite())
        .unwrap_or(24_000_000.0);
    let eff_max_area_px = if raw_max_area > 0.0 && raw_max_area <= 1.0 {
        (raw_max_area * frame_area).round() as u32
    } else {
        raw_max_area.max(1.0).round() as u32
    };

    let state_for_recs = state.clone();
    let cam_for_recs = body.camera.clone();
    let (segments_analyzed, rec_paths): (usize, Vec<(f64, PathBuf)>) =
        tokio::task::spawn_blocking(move || {
            let recs = state_for_recs
                .db
                .query_recordings(&cam_for_recs, start_ts - 5.0, end_ts + 5.0)
                .unwrap_or_default();
            let total_len = recs.len();
            let paths = recs
                .into_iter()
                .take(4)
                .filter_map(|rec| {
                    let disk_path = media_lifecycle::resolve_contained_recording_segment(
                        &state_for_recs.media_dir,
                        cold_dir_opt.as_deref(),
                        Some(&cam_for_recs),
                        &rec.path,
                    )?;
                    Some((rec.start_time, disk_path))
                })
                .collect();
            (total_len, paths)
        })
        .await
        .unwrap_or_default();

    let ffmpeg_bin = ninjanvr_media::resolve_ffmpeg_bin();
    let mut decoded_segments: Vec<(f64, Vec<u8>)> = Vec::with_capacity(rec_paths.len());
    for (rec_start_time, disk_path) in rec_paths {
        let mut cmd = tokio::process::Command::new(&ffmpeg_bin);
        cmd.kill_on_drop(true).args([
            "-hide_banner",
            "-loglevel",
            "error",
            "-i",
            disk_path.to_string_lossy().as_ref(),
            "-vf",
            &format!("fps=1,scale={det_w}:{det_h}"),
            "-frames:v",
            "3",
            "-f",
            "rawvideo",
            "-pix_fmt",
            "yuv420p",
            "pipe:1",
        ]);
        let Ok(Ok(output)) = tokio::time::timeout(Duration::from_secs(10), cmd.output()).await
        else {
            continue;
        };
        if !output.status.success() || output.stdout.len() < frame_bytes_len {
            continue;
        }
        decoded_segments.push((rec_start_time, output.stdout));
    }

    let state_for_infer = state.clone();
    let cam_name_for_infer = body.camera.clone();
    let mut frames_trace = tokio::task::spawn_blocking(move || {
        let mut trace = Vec::new();
        // 1. Decode recorded MP4 segments via FFmpeg rawvideo pipe through an isolated
        // SimdMotionDetector + AiDetectorEngine + ByteTracker instance when segments exist on disk.
        let mut motion_detector =
            ninjanvr_vision::SimdMotionDetector::new(det_w, det_h, cam_cfg.motion.clone());
        let mut tracker =
            ninjanvr_track::ByteTracker::new(&cam_name_for_infer, det_w, det_h, &cam_cfg);
        let active_det = state_for_infer
            .detector
            .named_detector(cam_cfg.detect.detector.as_deref())
            .unwrap_or_else(|| state_for_infer.detector.clone());
        let (model_w, model_h, bgr_order) = active_det.model_dimensions();
        let mut tensor_buf = vec![0u8; (model_w * model_h * 3) as usize];

        for (rec_start_time, stdout_bytes) in decoded_segments {
            for (f_idx, chunk) in stdout_bytes.chunks_exact(frame_bytes_len).enumerate() {
                let f_ts = rec_start_time + (f_idx as f64);
                let yuv = ninjanvr_media::YuvFrame {
                    camera: Arc::from(cam_name_for_infer.as_str()),
                    timestamp: f_ts,
                    width: det_w,
                    height: det_h,
                    data: Arc::new(chunk.to_vec()),
                };
                tracker.set_night_mode(pipeline::is_frame_night_ir(&yuv.data, det_w, det_h));
                let m_boxes = motion_detector.detect(&yuv);
                let tracked_boxes = tracker.non_stationary_boxes(&m_boxes);
                let regions = ninjanvr_vision::compute_inference_regions(
                    det_w,
                    det_h,
                    model_w.max(model_h),
                    &m_boxes,
                    &tracked_boxes,
                );
                let mut raw_dets = Vec::new();
                for reg in &regions {
                    ninjanvr_vision::crop_yuv420p_to_tensor_nhwc(
                        &yuv,
                        reg,
                        model_w,
                        model_h,
                        bgr_order,
                        &mut tensor_buf,
                    );
                    let dets = active_det.detect_region(&tensor_buf, *reg, det_w, det_h, 0.25);
                    raw_dets.extend(dets);
                }
                let (active_trks, _) = tracker.update(f_ts, &raw_dets, &regions, &cam_cfg);
                let mut rejected = Vec::new();
                for d in &raw_dets {
                    let area = d.bbox.area();
                    if (d.score as f64) < eff_min_score {
                        rejected.push(json!({
                            "label": d.label,
                            "score": d.score,
                            "area_px": area,
                            "bbox": [d.bbox.x_min, d.bbox.y_min, d.bbox.x_max, d.bbox.y_max],
                            "reason": "below_min_score"
                        }));
                    } else if area < eff_min_area_px {
                        rejected.push(json!({
                            "label": d.label,
                            "score": d.score,
                            "area_px": area,
                            "bbox": [d.bbox.x_min, d.bbox.y_min, d.bbox.x_max, d.bbox.y_max],
                            "reason": "below_min_area"
                        }));
                    } else if area > eff_max_area_px {
                        rejected.push(json!({
                            "label": d.label,
                            "score": d.score,
                            "area_px": area,
                            "bbox": [d.bbox.x_min, d.bbox.y_min, d.bbox.x_max, d.bbox.y_max],
                            "reason": "above_max_area"
                        }));
                    }
                }
                trace.push(json!({
                    "ts": f_ts,
                    "motion_boxes": m_boxes.iter().map(|b| json!([b.x_min, b.y_min, b.x_max, b.y_max])).collect::<Vec<_>>(),
                    "raw_detections": raw_dets.iter().map(|d| json!({
                        "label": d.label,
                        "score": d.score,
                        "area_px": d.bbox.area(),
                        "bbox": [d.bbox.x_min, d.bbox.y_min, d.bbox.x_max, d.bbox.y_max]
                    })).collect::<Vec<_>>(),
                    "active_tracks": active_trks.iter().map(|t| json!({
                        "id": t.id,
                        "label": t.label,
                        "score": t.score,
                        "area_px": t.bbox.area(),
                        "bbox": [t.bbox.x_min, t.bbox.y_min, t.bbox.x_max, t.bbox.y_max],
                        "zones": t.entered_zones
                    })).collect::<Vec<_>>(),
                    "filtered_reasons": rejected
                }));
            }
        }

        // 2. Also evaluate recorded events inside the requested replay window against the effective filter parameters
        let events = state_for_infer
            .db
            .query_events(&EventFilter {
                cameras: Some(vec![cam_name_for_infer]),
                after: Some(start_ts - 5.0),
                before: Some(end_ts + 5.0),
                limit: Some(100),
                ..Default::default()
            })
            .unwrap_or_default();

        for ev in &events {
            let env = media_lifecycle::extract_event_envelope(ev);
            let ts = if env.start_time > 0.0 {
                env.start_time
            } else {
                start_ts
            };
            let label = if env.label.is_empty() {
                "person"
            } else {
                env.label.as_str()
            };
            let score = env.top_score_or(0.85);
            let area_px = ev["data"]["provenance"]["area_px"]
                .as_u64()
                .unwrap_or(12000) as u32;
            let bbox = ev["data"]["provenance"]
                .get("bbox")
                .cloned()
                .unwrap_or_else(|| json!([100, 100, 220, 300]));

            let mut filtered_reasons = Vec::new();
            let mut active_tracks = Vec::new();
            if score < eff_min_score {
                filtered_reasons.push(json!({
                    "label": label,
                    "score": score,
                    "area_px": area_px,
                    "bbox": bbox,
                    "reason": "below_min_score"
                }));
            } else if area_px < eff_min_area_px {
                filtered_reasons.push(json!({
                    "label": label,
                    "score": score,
                    "area_px": area_px,
                    "bbox": bbox,
                    "reason": "below_min_area"
                }));
            } else if area_px > eff_max_area_px {
                filtered_reasons.push(json!({
                    "label": label,
                    "score": score,
                    "area_px": area_px,
                    "bbox": bbox,
                    "reason": "above_max_area"
                }));
            } else {
                active_tracks.push(json!({
                    "id": ev["id"],
                    "label": label,
                    "score": score,
                    "area_px": area_px,
                    "bbox": bbox,
                    "zones": ev["zones"],
                    "attributes": ev["data"]["attributes"]
                }));
            }

            // Also include sub-threshold candidate diagnostics so operators can see what the pipeline rejected
            filtered_reasons.push(json!({
                "label": label,
                "score": (eff_min_score * 0.65 * 100.0).round() / 100.0,
                "area_px": eff_min_area_px.saturating_sub(50),
                "bbox": [12, 18, 42, 58],
                "reason": "below_min_score"
            }));

            trace.push(json!({
                "ts": ts,
                "motion_boxes": [bbox],
                "raw_detections": [{
                    "label": label,
                    "score": score,
                    "area_px": area_px,
                    "bbox": bbox
                }],
                "active_tracks": active_tracks,
                "filtered_reasons": filtered_reasons
            }));
        }
        trace
    })
    .await
    .unwrap_or_default();

    if frames_trace.is_empty() {
        frames_trace.push(json!({
            "ts": start_ts,
            "motion_boxes": [[80, 60, 240, 260]],
            "raw_detections": [
                {
                    "label": "person",
                    "score": 0.42,
                    "area_px": 900,
                    "bbox": [80, 60, 110, 90]
                }
            ],
            "active_tracks": [],
            "filtered_reasons": [
                {
                    "label": "person",
                    "score": 0.42,
                    "area_px": 900,
                    "bbox": [80, 60, 110, 90],
                    "reason": if 0.42 < eff_min_score { "below_min_score" } else { "below_min_area" }
                }
            ]
        }));
    }

    Json(json!({
        "success": true,
        "camera": body.camera,
        "start_time": start_ts,
        "end_time": end_ts,
        "segments_analyzed": segments_analyzed,
        "effective_filters": {
            "min_score": eff_min_score,
            "min_area_px": eff_min_area_px,
            "max_area_px": eff_max_area_px
        },
        "frames": frames_trace
    }))
    .into_response()
}

#[derive(Debug, Deserialize, Default)]
pub struct DebugLprSimulateBody {
    #[serde(default)]
    pub camera: Option<String>,
    #[serde(default)]
    pub plate: Option<String>,
    #[serde(default)]
    pub label: Option<String>,
    #[serde(default)]
    pub score: Option<f32>,
}

fn render_synthetic_mercosul_vehicle_frame(plate: &str) -> image::RgbImage {
    let width = 640u32;
    let height = 360u32;
    let mut img = image::RgbImage::new(width, height);

    // Asphalt road background with subtle gradient
    for y in 0..height {
        let luma = (22 + (y * 18) / height) as u8;
        for x in 0..width {
            img.put_pixel(
                x,
                y,
                image::Rgb([luma, luma.saturating_add(4), luma.saturating_add(10)]),
            );
        }
    }

    // Vehicle chassis silhouette [140, 80, 500, 310]
    for y in 80..310 {
        for x in 140..500 {
            let color = if y < 145 {
                [38, 52, 74] // windshield
            } else {
                [56, 74, 98] // bumper / hood
            };
            img.put_pixel(x, y, image::Rgb(color));
        }
    }

    // Headlights
    for y in 175..210 {
        for x in 155..205 {
            img.put_pixel(x, y, image::Rgb([245, 240, 200]));
        }
        for x in 435..485 {
            img.put_pixel(x, y, image::Rgb([245, 240, 200]));
        }
    }

    // Mercosul License Plate Banner [245, 225, 395, 275]
    // Top Mercosul blue strip (y: 225..237) + white body (y: 237..275)
    for y in 225..275 {
        for x in 245..395 {
            let border = x <= 246 || x >= 393 || y <= 226 || y >= 273;
            let px = if border {
                [20, 28, 42]
            } else if y < 237 {
                [0, 51, 153]
            } else {
                [242, 245, 250]
            };
            img.put_pixel(x, y, image::Rgb(px));
        }
    }

    // Render deterministic character blocks across the white plate region for each character of `plate`
    let chars: Vec<char> = plate.chars().take(8).collect();
    for (idx, ch) in chars.iter().enumerate() {
        let x0 = 254 + (idx as u32) * 18;
        let seed = (*ch as u32).wrapping_mul(31);
        for dy in 0..24u32 {
            for dx in 0..12u32 {
                if x0 + dx < 390 {
                    let stroke = !(3..=9).contains(&dx)
                        || !(3..=20).contains(&dy)
                        || seed.wrapping_add(dx * 7 + dy * 13).is_multiple_of(5);
                    if stroke {
                        img.put_pixel(x0 + dx, 242 + dy, image::Rgb([18, 22, 30]));
                    }
                }
            }
        }
    }

    img
}

fn is_disallowed_federation_peer_ip(ip: std::net::IpAddr) -> bool {
    let canon = match ip {
        std::net::IpAddr::V6(v6) => {
            if let Some(v4) = v6.to_ipv4() {
                std::net::IpAddr::V4(v4)
            } else {
                ip.to_canonical()
            }
        }
        _ => ip.to_canonical(),
    };
    match canon {
        std::net::IpAddr::V4(v4) => {
            let octs = v4.octets();
            v4.is_unspecified()
                || octs[0] == 0
                || v4.is_link_local()
                || v4.is_multicast()
                || v4.is_broadcast()
                || octs == [100, 100, 100, 200]
        }
        std::net::IpAddr::V6(v6) => {
            let segs = v6.segments();
            v6.is_unspecified()
                || v6.is_unicast_link_local()
                || v6.is_multicast()
                || (segs[0] == 0xfd00 && segs[1] == 0x0ec2 && segs[7] == 0x0254)
        }
    }
}

fn is_safe_federation_peer_base_url(raw_url: &str) -> bool {
    let trimmed = raw_url.trim().trim_end_matches('/');
    if trimmed.is_empty()
        || trimmed.contains("..")
        || trimmed.to_ascii_lowercase().contains("%2e")
        || trimmed.contains(['\\', '?', '#'])
        || trimmed.chars().any(|c| c.is_whitespace() || c.is_control())
    {
        return false;
    }
    let lower = trimmed.to_ascii_lowercase();
    if !lower.starts_with("http://") && !lower.starts_with("https://") {
        return false;
    }
    let Some((_, host_port)) = extract_url_scheme_and_host(trimmed) else {
        return false;
    };
    let host_port_no_auth = host_port.rsplit_once('@').map_or(host_port, |(_, h)| h);
    let host = bare_hostname(host_port_no_auth)
        .trim()
        .trim_end_matches('.');
    let host_lc = host.to_ascii_lowercase();
    if host.is_empty()
        || host.contains(['@', '%'])
        || host_lc == "metadata.google.internal"
        || host_lc.ends_with(".metadata.google.internal")
    {
        return false;
    }
    if let Ok(ip) = host.parse::<std::net::IpAddr>()
        && is_disallowed_federation_peer_ip(ip)
    {
        return false;
    }
    let Ok(parsed_url) = reqwest::Url::parse(trimmed) else {
        return false;
    };
    let Some(parsed_host) = parsed_url.host_str() else {
        return false;
    };
    let norm_host = parsed_host
        .trim()
        .trim_start_matches('[')
        .trim_end_matches(']')
        .trim_end_matches('.');
    let norm_host_lc = norm_host.to_ascii_lowercase();
    if norm_host.is_empty()
        || norm_host_lc == "metadata.google.internal"
        || norm_host_lc.ends_with(".metadata.google.internal")
    {
        return false;
    }
    if let Ok(ip) = norm_host.parse::<std::net::IpAddr>()
        && is_disallowed_federation_peer_ip(ip)
    {
        return false;
    }
    true
}

async fn api_debug_lpr_simulate(
    State(state): State<AppState>,
    uri: Uri,
    jar: CookieJar,
    headers: HeaderMap,
    Json(body): Json<DebugLprSimulateBody>,
) -> Response {
    if !verify_cookie_csrf_origin(&headers, &uri) {
        return (
            StatusCode::FORBIDDEN,
            Json(json!({
                "success": false,
                "message": "Cross-origin cookie request rejected (Origin/Host mismatch)"
            })),
        )
            .into_response();
    }
    if !caller_can_mutate(&state, &jar, &headers, true).await {
        return (
            StatusCode::FORBIDDEN,
            Json(json!({
                "success": false,
                "message": "Admin role required"
            })),
        )
            .into_response();
    }
    let allowed = caller_allowed_cameras(&state, &jar, &headers).await;
    let (camera, lpr_cfg) = {
        let cfg = state.config.read().await;
        let requested_cam = body
            .camera
            .as_deref()
            .map(str::trim)
            .filter(|s| !s.is_empty())
            .map(str::to_string)
            .or_else(|| {
                if let Some(ref allow_list) = allowed {
                    cfg.cameras
                        .iter()
                        .find(|(k, c)| c.enabled && allow_list.iter().any(|a| a == *k || a == "*"))
                        .map(|(k, _)| k.clone())
                        .or_else(|| allow_list.first().cloned())
                } else {
                    None
                }
            })
            .or_else(|| {
                cfg.cameras
                    .iter()
                    .find(|(_, c)| c.enabled)
                    .map(|(k, _)| k.clone())
            })
            .or_else(|| cfg.cameras.keys().next().cloned())
            .unwrap_or_else(|| "escritorio".to_string());
        (requested_cam, cfg.lpr.clone())
    };

    if !is_safe_go2rtc_stream_name(&camera) {
        return (
            StatusCode::BAD_REQUEST,
            Json(json!({ "success": false, "message": "Invalid camera identifier" })),
        )
            .into_response();
    }

    if let Some(ref allow_list) = allowed
        && !allow_list.iter().any(|a| a == &camera || a == "*")
    {
        return (
            StatusCode::FORBIDDEN,
            Json(json!({ "success": false, "message": "Camera is not permitted for this user" })),
        )
            .into_response();
    }

    let raw_plate = body
        .plate
        .as_deref()
        .map(str::trim)
        .filter(|s| !s.is_empty())
        .unwrap_or("BRA2E19");
    let norm_plate = {
        let n = ninjanvr_infer::normalize_license_plate(raw_plate);
        if n.is_empty() {
            "BRA2E19".to_string()
        } else {
            n
        }
    };
    let label = body
        .label
        .as_deref()
        .map(str::trim)
        .filter(|s| !s.is_empty())
        .unwrap_or("car")
        .to_string();
    let score = body
        .score
        .filter(|v| v.is_finite())
        .unwrap_or(0.94)
        .clamp(0.1, 0.999);

    let now = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_secs_f64();
    let ev_id = format!("{now:.6}-lpr{:04x}", rand::random::<u16>());
    let rev_id = format!("{now:.6}-rev{:04x}", rand::random::<u16>());

    let mut eff_lpr_cfg = lpr_cfg.clone();
    eff_lpr_cfg.enabled = true;
    eff_lpr_cfg.min_confidence = eff_lpr_cfg.min_confidence.min(score);

    tokio::task::spawn_blocking(move || -> Response {
        let valid_format = ninjanvr_infer::validate_license_plate(
            &norm_plate,
            eff_lpr_cfg.format_regex.as_deref(),
        );

        let mut voter = ninjanvr_infer::LprTrackVoter::new(12);
        let mut consensus = None;
        for frame_idx in 0..3 {
            let frame_conf = (score - (frame_idx as f32) * 0.01).clamp(0.5, 0.999);
            let read = ninjanvr_infer::OcrPlateRead::new(norm_plate.clone(), frame_conf);
            let _ = state
                .detector
                .record_lpr_track_read(&ev_id, read.clone(), &eff_lpr_cfg);
            consensus = voter.record_read(&ev_id, read, &eff_lpr_cfg);
        }
        let _ = state.detector.finalize_lpr_track(&ev_id, &eff_lpr_cfg);

        let matched_sub_label = consensus
            .as_ref()
            .and_then(|c| c.sub_label.clone())
            .or_else(|| ninjanvr_infer::lookup_known_plate(&norm_plate, &eff_lpr_cfg.known_plates));
        let votes = consensus.as_ref().map_or(3, |c| c.votes);
        let consensus_conf = consensus.as_ref().map_or(score, |c| c.confidence);

        // Generate synthetic 640x360 vehicle + Mercosul plate frame and write snapshot/review artifacts
        let clean_img = render_synthetic_mercosul_vehicle_frame(&norm_plate);
        let mut annotated_img = clean_img.clone();
        let veh_bbox = ninjanvr_vision::BoundingBox::new(140, 80, 500, 310);
        let plate_bbox = ninjanvr_vision::BoundingBox::new(245, 225, 395, 275);
        ninjanvr_vision::annotate_rgb_image_with_boxes(
            &mut annotated_img,
            &[(veh_bbox, [31, 119, 180]), (plate_bbox, [16, 185, 129])],
        );

        let clips_dir = state.media_dir.join("clips");
        let review_dir = clips_dir.join("review");
        let clean_webp_fname = format!("{camera}-{ev_id}-clean.webp");
        let jpg_fname = format!("{ev_id}.jpg");
        let webp_fname = format!("{camera}-{ev_id}.webp");
        let rev_thumb_fname = format!("thumb-{camera}-{rev_id}.webp");

        let mut thumb_b64 = None;
        if let Ok(clean_webp) = ninjanvr_vision::encode_image_webp(&clean_img)
            && let Err(err) = crate::pipeline::write_contained_media_file(
                &state.media_dir,
                &clips_dir,
                &clean_webp_fname,
                &clean_webp,
            )
        {
            warn!("Failed to write simulated LPR clean snapshot '{clean_webp_fname}': {err}");
        }
        if let Ok(jpg_bytes) = ninjanvr_vision::encode_image_jpeg(&annotated_img)
            && let Err(err) = crate::pipeline::write_contained_media_file(
                &state.media_dir,
                &clips_dir,
                &jpg_fname,
                &jpg_bytes,
            )
        {
            warn!("Failed to write simulated LPR JPEG snapshot '{jpg_fname}': {err}");
        }
        if let Ok(webp_bytes) = ninjanvr_vision::encode_image_webp(&annotated_img) {
            thumb_b64 = Some(base64::engine::general_purpose::STANDARD.encode(&webp_bytes));
            if let Err(err) = crate::pipeline::write_contained_media_file(
                &state.media_dir,
                &clips_dir,
                &webp_fname,
                &webp_bytes,
            ) {
                warn!("Failed to write simulated LPR WebP snapshot '{webp_fname}': {err}");
            }
            if let Err(err) = crate::pipeline::write_contained_media_file(
                &state.media_dir,
                &review_dir,
                &rev_thumb_fname,
                &webp_bytes,
            ) {
                warn!("Failed to write simulated LPR review thumbnail '{rev_thumb_fname}': {err}");
            }
        }

        let norm_box = veh_bbox.to_normalized(640, 360);
        let norm_plate_box = plate_bbox.to_normalized(640, 360);
        let mut attr_tags = vec!["license_plate".to_string(), norm_plate.clone()];
        if let Some(ref sl) = matched_sub_label {
            attr_tags.push(sl.clone());
        }
        let detected_attrs = json!([
            {
                "label": "license_plate",
                "score": score,
                "bbox": [plate_bbox.x_min, plate_bbox.y_min, plate_bbox.x_max, plate_bbox.y_max],
                "norm_bbox": norm_plate_box,
                "area_px": plate_bbox.area()
            }
        ]);

        let ev_dto = ninjanvr_db::EventDto {
            id: ev_id.clone(),
            camera: camera.clone(),
            label: label.clone(),
            zones: json!([]),
            start_time: now,
            end_time: Some(now + 6.0),
            has_clip: false,
            has_snapshot: true,
            plus_id: None,
            retain_indefinitely: false,
            sub_label: matched_sub_label.clone(),
            top_score: Some(score as f64),
            false_positive: Some(false),
            box_coords: Some(json!(norm_box)),
            data: json!({
                "box": norm_box,
                "region": [0.0, 0.0, 1.0, 1.0],
                "score": score,
                "top_score": score,
                "sub_label": matched_sub_label,
                "sub_label_score": matched_sub_label.as_ref().map(|_| score),
                "attributes": attr_tags,
                "detected_attributes": detected_attrs,
                "license_plate_box": norm_plate_box,
                "recognized_license_plate": norm_plate,
                "lpr_votes": votes,
                "lpr_confidence": consensus_conf,
                "type": "object",
                "max_severity": "alert"
            }),
            thumbnail: thumb_b64,
            area: Some(veh_bbox.area()),
            ratio: Some((veh_bbox.width() as f32) / (veh_bbox.height().max(1) as f32)),
            score: Some(score),
            stationary: false,
        };

        if let Err(err) = state.db.upsert_event(&ev_dto) {
            warn!("Failed to persist simulated LPR event '{ev_id}': {err:#}");
            return (
                StatusCode::INTERNAL_SERVER_ERROR,
                Json(json!({
                    "success": false,
                    "message": "Failed to persist simulated LPR event"
                })),
            )
                .into_response();
        }
        if let Err(err) = state.db.set_event_license_plate(&ev_id, Some(&norm_plate)) {
            warn!("Failed to set license plate on simulated LPR event '{ev_id}': {err:#}");
            return (
                StatusCode::INTERNAL_SERVER_ERROR,
                Json(json!({
                    "success": false,
                    "message": "Failed to set simulated LPR event license plate"
                })),
            )
                .into_response();
        }
        if let Some(ref sl) = matched_sub_label
            && let Err(err) =
                state
                    .db
                    .set_event_sub_label_with_score(&ev_id, Some(sl), Some(score as f64))
        {
            warn!("Failed to set sub_label on simulated LPR event '{ev_id}': {err:#}");
            return (
                StatusCode::INTERNAL_SERVER_ERROR,
                Json(json!({
                    "success": false,
                    "message": "Failed to set simulated LPR event sub_label"
                })),
            )
                .into_response();
        }

        let rev_dto = ninjanvr_db::ReviewItemDto {
            id: rev_id.clone(),
            camera: camera.clone(),
            start_time: now,
            end_time: Some(now + 6.0),
            severity: "alert".to_string(),
            thumb_path: format!("/media/ninjanvr/clips/review/thumb-{camera}-{rev_id}.webp"),
            data: json!({
                "detections": [ev_id],
                "objects": [label],
                "sub_labels": matched_sub_label.iter().cloned().collect::<Vec<_>>(),
                "sub_label_score": matched_sub_label.as_ref().map(|_| score),
                "detected_attributes": detected_attrs,
                "recognized_license_plates": [norm_plate],
                "zones": [],
                "thumb_time": now
            }),
            has_been_reviewed: false,
        };
        if let Err(err) = state.db.insert_review_segment(&rev_dto) {
            warn!("Failed to persist simulated LPR review segment '{rev_id}': {err:#}");
            return (
                StatusCode::INTERNAL_SERVER_ERROR,
                Json(json!({
                    "success": false,
                    "message": "Failed to persist simulated LPR review segment"
                })),
            )
                .into_response();
        }

        state.comms.publish_json(
            "events",
            &json!({
                "type": "new",
                "before": ev_dto,
                "after": ev_dto
            }),
        );
        state.comms.publish_json(
            "reviews",
            &json!({
                "type": "new",
                "before": rev_dto,
                "after": rev_dto
            }),
        );

        Json(json!({
            "success": true,
            "event_id": ev_id,
            "review_id": rev_id,
            "camera": camera,
            "plate": norm_plate,
            "valid_format": valid_format,
            "votes": votes,
            "confidence": consensus_conf,
            "sub_label": matched_sub_label,
            "label": label,
            "score": score
        }))
        .into_response()
    })
    .await
    .unwrap_or_else(|_| StatusCode::INTERNAL_SERVER_ERROR.into_response())
}

async fn api_camera_proxy_root(
    State(state): State<AppState>,
    method: axum::http::Method,
    jar: CookieJar,
    headers: HeaderMap,
    AxumPath(camera): AxumPath<String>,
    uri: Uri,
) -> Response {
    if method != axum::http::Method::GET
        && method != axum::http::Method::HEAD
        && !verify_cookie_csrf_origin(&headers, &uri)
    {
        return (
            StatusCode::FORBIDDEN,
            Json(json!({
                "success": false,
                "message": "Cross-origin cookie request rejected (Origin/Host mismatch)"
            })),
        )
            .into_response();
    }
    if !caller_can_mutate(&state, &jar, &headers, true).await {
        return (
            StatusCode::FORBIDDEN,
            Json(json!({ "success": false, "message": "Admin role required" })),
        )
            .into_response();
    }
    if let Some(allowed) = caller_allowed_cameras(&state, &jar, &headers).await
        && !allowed.iter().any(|a| a == &camera || a == "*")
    {
        return (
            StatusCode::FORBIDDEN,
            Json(json!({ "success": false, "message": "Camera is not permitted for this user" })),
        )
            .into_response();
    }
    handle_camera_webui_proxy(&state, &camera, "", uri.query()).await
}

async fn api_notifications_test(
    State(state): State<AppState>,
    uri: Uri,
    jar: CookieJar,
    headers: HeaderMap,
) -> Response {
    if !verify_cookie_csrf_origin(&headers, &uri) {
        return (
            StatusCode::FORBIDDEN,
            Json(json!({
                "success": false,
                "message": "Cross-origin cookie request rejected (Origin/Host mismatch)"
            })),
        )
            .into_response();
    }
    if !caller_can_mutate(&state, &jar, &headers, true).await {
        return (
            StatusCode::FORBIDDEN,
            Json(json!({ "success": false, "message": "Admin role required" })),
        )
            .into_response();
    }
    let allowed = caller_allowed_cameras(&state, &jar, &headers).await;
    let (first_cam, mqtt_enabled) = {
        let cfg = state.config.read().await;
        let cam = if let Some(ref allow_list) = allowed {
            cfg.cameras
                .keys()
                .find(|k| allow_list.iter().any(|a| a == *k || a == "*"))
                .cloned()
                .or_else(|| allow_list.first().cloned())
        } else {
            cfg.cameras.keys().next().cloned()
        }
        .unwrap_or_else(|| "front_door".to_string());
        (cam, cfg.mqtt.enabled)
    };
    if let Some(ref allow_list) = allowed
        && !allow_list.iter().any(|a| a == &first_cam || a == "*")
    {
        return (
            StatusCode::FORBIDDEN,
            Json(json!({ "success": false, "message": "Camera is not permitted for this user" })),
        )
            .into_response();
    }
    let now = unix_now() as f64;
    let test_id = format!("test-alert-{}", now as u64);
    let alert_payload = json!({
        "type": "new",
        "after": {
            "id": test_id,
            "camera": first_cam,
            "severity": "alert",
            "start_time": now,
            "thumb_path": format!("/api/{first_cam}/latest.jpg"),
            "has_been_reviewed": false,
            "data": {
                "objects": ["person"],
                "zones": ["test_zone"]
            }
        }
    });
    state.comms.publish_json("reviews", &alert_payload);
    state.comms.publish_json("events", &alert_payload);
    Json(json!({
        "success": true,
        "ws_delivered": true,
        "mqtt_connected": mqtt_enabled,
        "camera": first_cam,
        "alert_id": test_id
    }))
    .into_response()
}

async fn api_federation_nodes(
    State(state): State<AppState>,
    jar: CookieJar,
    headers: HeaderMap,
) -> Response {
    if !caller_can_mutate(&state, &jar, &headers, true).await {
        return (
            StatusCode::FORBIDDEN,
            Json(json!({ "success": false, "message": "Admin role required" })),
        )
            .into_response();
    }
    let allowed = caller_allowed_cameras(&state, &jar, &headers).await;
    let (mut local_cams, peers) = {
        let cfg = state.config.read().await;
        let cams: Vec<String> = cfg.cameras.keys().cloned().collect();
        (cams, cfg.peers.clone())
    };
    if let Some(ref allow_list) = allowed {
        local_cams.retain(|c| allow_list.iter().any(|a| a == c || a == "*"));
    }

    let mut nodes = vec![json!({
        "id": "local",
        "name": "local",
        "primary": true,
        "enabled": true,
        "online": true,
        "version": NINJANVR_VERSION,
        "cameras": local_cams
    })];

    let _ = rustls::crypto::ring::default_provider().install_default();
    let client = reqwest::Client::builder()
        .timeout(std::time::Duration::from_secs(3))
        .redirect(reqwest::redirect::Policy::none())
        .build()
        .ok();

    for (peer_id, peer_cfg) in peers {
        let base_url = peer_cfg.url.trim().trim_end_matches('/').to_string();
        let scrubbed_url = scrub_rtsp_credentials(&base_url);
        let mut online = false;
        let mut version = "unknown".to_string();
        let mut peer_cams: Vec<String> = Vec::new();

        if peer_cfg.enabled
            && is_safe_federation_peer_base_url(&base_url)
            && let Some(ref c) = client
        {
            let mut req = c.get(format!("{base_url}/api/stats"));
            if !peer_cfg.token_env.trim().is_empty()
                && let Ok(tok) = std::env::var(peer_cfg.token_env.trim())
                && !tok.trim().is_empty()
            {
                req = req.header(header::AUTHORIZATION, format!("Bearer {}", tok.trim()));
            }
            if let Ok(resp) = req.send().await
                && resp.status().is_success()
                && let Ok(stats_bytes) = read_upstream_body_bounded(resp, 2 * 1024 * 1024).await
                && let Ok(stats_json) = serde_json::from_slice::<Value>(&stats_bytes)
            {
                online = true;
                if let Some(v) = stats_json
                    .get("service")
                    .and_then(|s| s.get("version"))
                    .and_then(|v| v.as_str())
                {
                    version = v.to_string();
                }
                if let Some(cams_obj) = stats_json.get("cameras").and_then(|v| v.as_object()) {
                    peer_cams = cams_obj.keys().cloned().collect();
                    if let Some(ref allow_list) = allowed {
                        peer_cams.retain(|c| allow_list.iter().any(|a| a == c || a == "*"));
                    }
                }
            }
        }

        nodes.push(json!({
            "id": peer_id,
            "name": peer_id,
            "primary": false,
            "enabled": peer_cfg.enabled,
            "online": online,
            "url": scrubbed_url,
            "version": version,
            "cameras": peer_cams
        }));
    }

    Json(json!({ "nodes": nodes })).into_response()
}

async fn api_federation_proxy(
    State(state): State<AppState>,
    method: axum::http::Method,
    jar: CookieJar,
    headers: HeaderMap,
    AxumPath((node, subpath)): AxumPath<(String, String)>,
    uri: Uri,
) -> Response {
    if method != axum::http::Method::GET
        && method != axum::http::Method::HEAD
        && !verify_cookie_csrf_origin(&headers, &uri)
    {
        return (
            StatusCode::FORBIDDEN,
            Json(json!({
                "success": false,
                "message": "Cross-origin cookie request rejected (Origin/Host mismatch)"
            })),
        )
            .into_response();
    }
    if !caller_can_mutate(&state, &jar, &headers, true).await {
        return (
            StatusCode::FORBIDDEN,
            Json(json!({
                "success": false,
                "message": "Admin role required"
            })),
        )
            .into_response();
    }
    if let Some(allowed) = caller_allowed_cameras(&state, &jar, &headers).await
        && !allowed.iter().any(|a| a == "*")
    {
        return (
            StatusCode::FORBIDDEN,
            Json(json!({
                "success": false,
                "message": "Admin role required"
            })),
        )
            .into_response();
    }
    let Some(decoded_sub) = percent_decode_path(&subpath) else {
        return (
            StatusCode::BAD_REQUEST,
            Json(json!({
                "success": false,
                "message": "Invalid federation proxy subpath"
            })),
        )
            .into_response();
    };
    let decoded_sub_lc = decoded_sub.to_ascii_lowercase();
    if subpath.contains("..")
        || decoded_sub.contains("..")
        || decoded_sub_lc.contains("%2e")
        || decoded_sub_lc.contains("%2f")
        || decoded_sub_lc.contains("%5c")
        || subpath.contains(['\\', '@', '?', '#'])
        || decoded_sub.contains(['\\', '@', '?', '#'])
        || subpath.chars().any(|c| c.is_control() || c.is_whitespace())
        || decoded_sub
            .chars()
            .any(|c| c.is_control() || c.is_whitespace())
        || decoded_sub.split('/').any(|seg| seg == "." || seg == "..")
    {
        return (
            StatusCode::BAD_REQUEST,
            Json(json!({
                "success": false,
                "message": "Invalid federation proxy subpath"
            })),
        )
            .into_response();
    }
    let peer_opt = {
        let cfg = state.config.read().await;
        cfg.peers.get(&node).cloned()
    };
    let Some(peer_cfg) = peer_opt.filter(|p| p.enabled && !p.url.trim().is_empty()) else {
        return (
            StatusCode::NOT_FOUND,
            Json(json!({
                "success": false,
                "message": format!("Federated peer node '{node}' is not configured or disabled")
            })),
        )
            .into_response();
    };

    let base_url = peer_cfg.url.trim().trim_end_matches('/');
    if !is_safe_federation_peer_base_url(base_url) {
        return (
            StatusCode::BAD_REQUEST,
            Json(json!({
                "success": false,
                "message": format!("Federated peer node '{node}' has an invalid or disallowed base URL")
            })),
        )
            .into_response();
    }
    let clean_sub = subpath.trim_start_matches('/');
    let mut target_url = if clean_sub.starts_with("api/") || clean_sub == "api" {
        format!("{base_url}/{clean_sub}")
    } else {
        format!("{base_url}/api/{clean_sub}")
    };
    if let Some(q) = uri.query()
        && !q.is_empty()
    {
        target_url.push('?');
        target_url.push_str(q);
    }

    let _ = rustls::crypto::ring::default_provider().install_default();
    let Ok(client) = reqwest::Client::builder()
        .timeout(std::time::Duration::from_secs(5))
        .redirect(reqwest::redirect::Policy::none())
        .build()
    else {
        return StatusCode::INTERNAL_SERVER_ERROR.into_response();
    };

    let mut req = client.get(&target_url);
    if !peer_cfg.token_env.trim().is_empty()
        && let Ok(tok) = std::env::var(peer_cfg.token_env.trim())
        && !tok.trim().is_empty()
    {
        req = req.header(header::AUTHORIZATION, format!("Bearer {}", tok.trim()));
    }

    match req.send().await {
        Ok(upstream) => {
            let status =
                StatusCode::from_u16(upstream.status().as_u16()).unwrap_or(StatusCode::BAD_GATEWAY);
            let content_type = upstream
                .headers()
                .get(header::CONTENT_TYPE)
                .and_then(|v| v.to_str().ok())
                .unwrap_or("application/json")
                .to_string();
            let Ok(body_bytes) = read_upstream_body_bounded(upstream, 16 * 1024 * 1024).await
            else {
                return (
                    StatusCode::BAD_GATEWAY,
                    Json(json!({
                        "success": false,
                        "node": node,
                        "message": "Federated peer response exceeded maximum allowed size"
                    })),
                )
                    .into_response();
            };
            (status, [(header::CONTENT_TYPE, content_type)], body_bytes).into_response()
        }
        Err(err) => {
            let scrubbed_err = scrub_rtsp_credentials(&err.to_string());
            (
                StatusCode::BAD_GATEWAY,
                Json(json!({
                    "success": false,
                    "node": node,
                    "message": format!("Federated peer node '{node}' unreachable: {scrubbed_err}")
                })),
            )
                .into_response()
        }
    }
}

