#[derive(Debug, Deserialize, Default)]
pub struct FalsePositiveBody {
    #[serde(default = "default_true")]
    pub false_positive: bool,
}

async fn api_event_false_positive(
    State(state): State<AppState>,
    jar: CookieJar,
    uri: Uri,
    headers: HeaderMap,
    AxumPath(id): AxumPath<String>,
    body: Option<Json<FalsePositiveBody>>,
) -> Response {
    if !verify_cookie_csrf_origin(&headers, &uri) {
        return (
            StatusCode::FORBIDDEN,
            Json(json!({
                "success": false,
                "message": "Cross-origin cookie request rejected (Origin/Host mismatch)"
            })),
        )
            .into_response();
    }
    if !caller_can_mutate(&state, &jar, &headers, false).await {
        return (
            StatusCode::FORBIDDEN,
            Json(json!({ "success": false, "message": "Read-only role cannot modify events" })),
        )
            .into_response();
    }
    if let Some(allowed) = effective_caller_allowed_cameras(&state, &jar, &headers).await {
        let permitted = state
            .db
            .get_event(&id)
            .ok()
            .flatten()
            .and_then(|ev| {
                ev["camera"]
                    .as_str()
                    .map(|c| allowed.iter().any(|a| a == c))
            })
            .unwrap_or(false);
        if !permitted {
            return (
                StatusCode::FORBIDDEN,
                Json(
                    json!({ "success": false, "message": "Camera is not permitted for this user" }),
                ),
            )
                .into_response();
        }
    }
    let fp = body.is_none_or(|b| b.0.false_positive);
    if let Err(err) = state.db.set_event_false_positive(&id, fp) {
        warn!("Failed to set event '{id}' false_positive={fp}: {err}");
        return (
            StatusCode::INTERNAL_SERVER_ERROR,
            Json(json!({
                "success": false,
                "message": "Failed to update event false_positive state"
            })),
        )
            .into_response();
    }
    if fp {
        let _ = create_dataset_sample_from_event_with_config(
            Some(&state.config),
            &state.db,
            &state.media_dir,
            &id,
            "hard_negative",
            None,
        )
        .await;
    } else {
        let sample_id = if id.starts_with("ds_") {
            id.clone()
        } else {
            format!("ds_{id}")
        };
        if let Ok(Some(existing)) = state.db.get_dataset_sample(&sample_id)
            && existing.sample_kind == "hard_negative"
        {
            dataset_catalog::delete_sample_artifacts(
                &state.media_dir,
                &existing.id,
                Some(&existing.image_path),
            );
            let _ = state.db.delete_dataset_sample(&sample_id);
        }
    }
    Json(json!({ "success": true, "false_positive": fp })).into_response()
}

